package com.bplus.share;
import org.json.*;import java.io.*;
/** Build-code metadata survives display-version resets. APK signature and versionCode still guard installation. */
public final class ReleaseChoice{
 public static JSONObject choose(JSONArray releases,boolean tests,String installed)throws Exception{JSONObject best=null;String highest=installed;for(int i=0;i<releases.length();i++){JSONObject r=releases.optJSONObject(i);if(r==null||r.optBoolean("draft")||(!tests&&r.optBoolean("prerelease")))continue;String version=r.optString("tag_name");try{if(!UpdateHttp.newer(version,highest))continue;}catch(IOException e){continue;}try{UpdateAsset.exact(r);}catch(Exception invalid){continue;}best=r;highest=version;}return best;}
 public static int buildCode(JSONObject release)throws IOException{String body=release.optString("body","");java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?m)^BPLUS_VERSION_CODE: ([1-9][0-9]{0,8})\\r?$").matcher(body);if(!m.find())return -1;int code=Integer.parseInt(m.group(1));if(m.find())throw new IOException("Duplicate release build metadata");return code;}
 public static boolean newer(JSONObject release,String installed,int installedCode)throws Exception{int code=buildCode(release);return code>0?code>installedCode:UpdateHttp.newer(release.optString("tag_name"),installed);}
 public static JSONObject choose(JSONArray releases,boolean tests,String installed,int installedCode)throws Exception{JSONObject best=null;int bestCode=installedCode;String highest=installed;for(int i=0;i<releases.length();i++){JSONObject r=releases.optJSONObject(i);if(r==null||r.optBoolean("draft")||(!tests&&r.optBoolean("prerelease")))continue;try{if(!newer(r,installed,installedCode))continue;int code=buildCode(r);if(best!=null){if(code>0&&bestCode>installedCode){if(code<=bestCode)continue;}else if(code<=0&&bestCode>installedCode)continue;else if(code<=0&&!UpdateHttp.newer(r.optString("tag_name"),highest))continue;}try{UpdateAsset.exact(r);}catch(Exception invalid){continue;}best=r;highest=r.optString("tag_name");bestCode=code;}catch(IOException ignored){}}return best;}
}
